document.addEventListener('DOMContentLoaded',()=>{const contentArea=document.querySelector('.md-content__inner');if(!contentArea)return;const triggers=document.querySelectorAll('.hover-trigger');triggers.forEach(trigger=>{const box=trigger.querySelector('.hover-box');const positionBox=()=>{box.classList.remove('show-below','align-left','align-right');const contentRect=contentArea.getBoundingClientRect();const boxRect=box.getBoundingClientRect();const triggerRect=trigger.getBoundingClientRect();if(triggerRect.top<boxRect.height+20){box.classList.add('show-below');}
if(boxRect.right>contentRect.right){box.classList.add('align-right');}
if(boxRect.left<contentRect.left){box.classList.add('align-left');}};trigger.addEventListener('mouseenter',()=>{box.style.visibility='visible';box.style.opacity='0';positionBox();box.style.opacity='1';});trigger.addEventListener('mouseleave',()=>{box.style.visibility='hidden';box.style.opacity='0';});});});